import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"第一章 基本规定","description":"","frontmatter":{"title":"第一章 基本规定","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/diyizhang：jibenguiding.md","filePath":"blogs/CC/第一章：基本规定.md"}'),o={name:"blogs/CC/diyizhang：jibenguiding.md"};function h(l,a,n,d,s,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h3 id="第一条" tabindex="-1">第一条 <a class="header-anchor" href="#第一条" aria-label="Permalink to &quot;第一条&quot;">​</a></h3><p>为了保护民事主体的合法权益，调整民事关系，维护社会和经济秩序，适应中国特色社会主义发展要求，弘扬社会主义核心价值观，根据宪法，制定本法。</p><h3 id="第二条" tabindex="-1">第二条 <a class="header-anchor" href="#第二条" aria-label="Permalink to &quot;第二条&quot;">​</a></h3><p>民法调整平等主体的自然人、法人和非法人组织之间的人身关系和财产关系。</p><h3 id="第三条" tabindex="-1">第三条 <a class="header-anchor" href="#第三条" aria-label="Permalink to &quot;第三条&quot;">​</a></h3><p>民事主体的人身权利、财产权利以及其他合法权益受法律保护，任何组织或者个人不得侵犯。</p><h3 id="第四条" tabindex="-1">第四条 <a class="header-anchor" href="#第四条" aria-label="Permalink to &quot;第四条&quot;">​</a></h3><p>民事主体在民事活动中的法律地位一律平等。</p><h3 id="第五条" tabindex="-1">第五条 <a class="header-anchor" href="#第五条" aria-label="Permalink to &quot;第五条&quot;">​</a></h3><p>民事主体从事民事活动，应当遵循自愿原则，按照自己的意思设立、变更、终止民事法律关系。</p><h3 id="第六条" tabindex="-1">第六条 <a class="header-anchor" href="#第六条" aria-label="Permalink to &quot;第六条&quot;">​</a></h3><p>民事主体从事民事活动，应当遵循公平原则，合理确定各方的权利和义务。</p><h3 id="第七条" tabindex="-1">第七条 <a class="header-anchor" href="#第七条" aria-label="Permalink to &quot;第七条&quot;">​</a></h3><p>民事主体从事民事活动，应当遵循诚信原则，秉持诚实，恪守承诺。</p><h3 id="第八条" tabindex="-1">第八条 <a class="header-anchor" href="#第八条" aria-label="Permalink to &quot;第八条&quot;">​</a></h3><p>民事主体从事民事活动，不得违反法律，不得违背公序良俗。</p><h3 id="第九条" tabindex="-1">第九条 <a class="header-anchor" href="#第九条" aria-label="Permalink to &quot;第九条&quot;">​</a></h3><p>民事主体从事民事活动，应当有利于节约资源、保护生态环境。</p><h3 id="第十条" tabindex="-1">第十条 <a class="header-anchor" href="#第十条" aria-label="Permalink to &quot;第十条&quot;">​</a></h3><p>处理民事纠纷，应当依照法律；法律没有规定的，可以适用习惯，但是不得违背公序良俗。</p><h3 id="第十一条" tabindex="-1">第十一条 <a class="header-anchor" href="#第十一条" aria-label="Permalink to &quot;第十一条&quot;">​</a></h3><p>其他法律对民事关系有特别规定的，依照其规定。</p><h3 id="第十二条" tabindex="-1">第十二条 <a class="header-anchor" href="#第十二条" aria-label="Permalink to &quot;第十二条&quot;">​</a></h3><p>中华人民共和国领域内的民事活动，适用中华人民共和国法律。法律另有规定的，依照其规定。</p>',24)])])}const b=e(o,[["render",h]]);export{u as __pageData,b as default};
